WITH valid AS (SELECT *, DATEDIFF(CURRENT_DATE(), opened_date) days_since_opened_date FROM accounts WHERE opened_date >= DATE '2023-02-28') SELECT id, account_type, opened_date, NTILE(10) OVER (PARTITION BY status, account_type ORDER BY balance DESC, id) balance_bucket, ROW_NUMBER() OVER (ORDER BY balance, id) row_seq, ROW_NUMBER() OVER (PARTITION BY account_type, customer_id ORDER BY balance, id) row_seq_2 FROM valid WHERE account_type = 'SAVINGS'
